insert into restaurante.mesas (empresa_id, numero, capacidade, area)
select '11111111-1111-1111-1111-111111111111', n,
  (array[2,2,4,4,4,6,2,4,6,8])[((n-1) % 10) + 1],
  case when n<=10 then 'Salão' when n<=18 then 'Varanda' else 'Área Externa' end
from generate_series(1,25) as n;

