insert into restaurante.ficha_tecnica (produto_id, insumo_id, quantidade)
select p.id, i.id, v.quantidade
from (values
  ('Picanha na Brasa (300g)','10000000-0000-0000-0000-000000000001'::uuid,0.3),
  ('Costela Bovina 12h','10000000-0000-0000-0000-000000000002'::uuid,0.4),
  ('Fraldinha Grelhada','10000000-0000-0000-0000-000000000003'::uuid,0.35),
  ('Ancho Premium','10000000-0000-0000-0000-000000000004'::uuid,0.32),
  ('Linguiça Artesanal','10000000-0000-0000-0000-000000000005'::uuid,0.25),
  ('Frango Caipira na Brasa','10000000-0000-0000-0000-000000000006'::uuid,0.4),
  ('Cupim Desfiado','10000000-0000-0000-0000-000000000007'::uuid,0.3)
) as v(produto_nome, insumo_id, quantidade)
join restaurante.produtos p on p.nome = v.produto_nome and p.empresa_id = '11111111-1111-1111-1111-111111111111'
join restaurante.insumos i on i.id = v.insumo_id
on conflict do nothing;

